 Object.defineProperty(navigator,'serviceWorker',{value:{register:async()=>({}),getRegistrations:async()=>[],addEventListener(){}},configurable:true});
 document.addEventListener('click',e=>{const a=e.target.closest?.('a[download]');if(!a)return;const u=new URL(a.href,location.href);if(u.origin!==location.origin||!u.pathname.startsWith('/api/'))return;e.preventDefault();e.stopImmediatePropagation();fetch(a.href).then(async r=>{if(!r.ok)throw Error('Export failed');const blob=await r.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=a.download||'Spire.zip';link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}).catch(()=>alert('The export could not be saved. Your local files are unchanged.'));},true);
 ready=createLocalRuntime({manual:true,structureOnly:true,load:()=>call('browse'),list:(path)=>call('list',{path}),readText:(path)=>call('text',{path}),reference:(path)=>call('reference',{path}),read:(path,reference)=>call('read',{path,reference}),commit:(before,after)=>call('commit',compactCommit(before,after))},workspace);
 globalThis.spireListFolder=async path=>{const response=await (await ready).fetch('/api/local/list',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});if(!response.ok)throw Error((await response.json()).error||'Folder listing failed');globalThis.dispatchEvent(new Event('spire-directory-listed'));};
 // Handle provider failure immediately, even while the editor module is importing.
